        /**
         * Resume a paused subscription
         * @description Billing is in advance, so what a resume charges depends on whether the paid term is still running. Resumed INSIDE the current term (before `current_period_end`), the subscription continues that term unchanged and nothing new is charged; `charges_handling` is ignored. Resumed AFTER the term ended, a new term starts now and is always billed: `invoice_immediately` raises its invoice and collects it (returned as `latest_invoice`), `add_to_unbilled_charges` parks the full recurring amount for the next invoice. Omitted, the business's `pause_config.charges_on_resume` decides.
         */
        post: {
            parameters: {
                query?: never;
                header?: {
                    /** @description Safely retry writes — repeats return the original response. If a write FAILED after it had already taken effect, that failure is what repeats: the key is spent, and a new attempt needs a new key. */
                    "Idempotency-Key"?: string;
                };
                path: {
                    /** @description Business id (biz_…) */
                    biz: string;
                    /** @description Subscription id (sub_…) */
                    sub: string;
                };
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        /**
                         * @description How a resume after the term ended bills the new term. Omitted: the business default.
                         * @enum {string}
                         */
                        charges_handling?: "invoice_immediately" | "add_to_unbilled_charges";
                        /**
                         * @description `schedule_payment_collection` attempts collection on the subscription's open invoices.
                         * @enum {string}
                         */
                        unpaid_invoices_handling?: "no_action" | "schedule_payment_collection";
                        /**
                         * @description `specific_date` schedules the resume for `resume_date` (a `resume` scheduled change carrying the two options above) and returns `scheduled_change` + `resume_scheduled_at`. Omitted: now.
                         * @enum {string}
                         */
                        resume_option?: "immediately" | "specific_date";
                        /**
                         * Format: date-time
                         * @description Required with `resume_option=specific_date`; in the future and before any scheduled cancellation.
                         */
                        resume_date?: string;
                    };
                };
            };
            responses: {
                /** @description Success */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Subscription"];
                    };
                };
                /** @description Idempotency-Key conflict — the key is already in flight, or was reused with a different request payload. */
                409: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Error"];
                    };
                };
            };
        };
        delete?: never;
