    "/v1/businesses/{biz}/invoices/{inv}/pay": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Record an offline/manual payment (or mark-paid)
         * @description A debit still in progress on the invoice is cancelled at its gateway first, so the payer does not pay twice. If the gateway does not cancel it, the payment is refused with a 409.
         */
        post: {
            parameters: {
                query?: never;
                header?: {
                    /** @description Safely retry writes — repeats return the original response. If a write FAILED after it had already taken effect, that failure is what repeats: the key is spent, and a new attempt needs a new key. */
                    "Idempotency-Key"?: string;
                };
                path: {
                    /** @description Business id (biz_…) */
                    biz: string;
                    /** @description The invoice's id (inv_…). */
                    inv: string;
                };
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        /** @description The amount paid, in minor units. */
                        amount_minor?: number;
                        /** @description How the customer paid. */
                        method?: string;
                        /**
                         * Format: date-time
                         * @description When the money arrived, if not now. The payment, its transaction, its ledger postings and the invoice's `paid_at` carry it. Not in the future, not before the invoice was raised.
                         */
                        date?: string;
                        /** @description The payer's reference (cheque number, wire reference). Stored as the transaction's `id_at_gateway`. */
                        reference?: string;
                        /** @description Operator note, kept as a comment on the invoice. */
                        comment?: string;
                        /**
                         * @description When `amount_minor` is less than the amount due, for this call only. `write_off`: the rest is written off with an adjustment credit note and the invoice is paid; it must fit the business limit (`billing_rules_config.partial_payment_write_off` for the currency and `partial_payment_write_off_max_percent` of the total), else the call is refused with a 400 and nothing is recorded. `leave_due`: the rest stays due. Omitted: the business rule (written off when it fits the limit). No effect when nothing is left due.
                         * @enum {string}
                         */
                        shortfall?: "write_off" | "leave_due";
                        /**
                         * @description When `amount_minor` is more than the amount due. `credit` (default): the rest is kept as the customer's excess credit (`excess_credited_minor`). `refund`: the rest is recorded as returned to the payer by the same offline method, as a succeeded `refund` transaction (`excess_refunded_minor`). The default is `credit` whatever `payment_application.excess_payment` says: that rule is for gateway payments.
                         * @enum {string}
                         */
                        excess?: "credit" | "refund";
                    };
                };
            };
            responses: {
                /** @description Success */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Invoice"];
                    };
                };
                /** @description Not payable, or a `write_off` above the business limit */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Error"];
                    };
                };
                /** @description A debit is in progress on the invoice and its gateway did not cancel it (`code: debit_in_progress`) */
                409: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Error"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
